question.template:
import os

# ── 1. Hintergrundklasse auf Festplatte schreiben ──────────────────────────
background_class_code = '''abstract class [Basisklasse] {
    protected int sharedValue;

    public [Basisklasse](int initialValue) {
        this.sharedValue = initialValue;
    }

    public abstract void doSomething();
}'''
with open('[Basisklasse].java', 'w') as f:
    f.write(background_class_code)

# ── 2. Studenten-Code auf Festplatte schreiben ─────────────────────────────
student_answer = """{{ STUDENT_ANSWER | e('py') }}"""
with open('[Unterklasse].java', 'w') as f:
    f.write(student_answer)

# ── 3. CodeRunner Testfall auf Festplatte schreiben ────────────────────────
testcode = """{{ TEST.testcode | e('py') }}"""
test_class = '''public class Test {
    public static void main(String[] args) throws Exception {
        ''' + testcode + '''
    }
}'''
with open('Test.java', 'w') as f:
    f.write(test_class)

# ── 4. Alles zusammen kompilieren incl. JVM Memory Limits (KRITISCH!) ──────
# Fehlen die Memory-Limits, stürzt die 64-Bit Sandbox mit einem 1GB Class Space Allocation Fehler ab.
ret = os.system('javac -J-Xmx128m -J-XX:CompressedClassSpaceSize=64m -encoding UTF-8 [Basisklasse].java [Unterklasse].java Test.java 2>&1')
if ret == 0:
    os.system('java -Xmx128m -XX:CompressedClassSpaceSize=64m -cp . Test')

question.answer:
public class [Unterklasse] extends [Basisklasse] {

    public [Unterklasse](int value) {
        super(value);
    }

    @Override
    public void doSomething() {
        this.sharedValue += 1;
    }
}
